const std = @import("std");

fn partition(arr: []i32, low: usize, high: usize) usize {
    const pivot = arr[high];
    var i: usize = low;
    var j: usize = low;
    while (j < high) {
        if (arr[j] < pivot) {
            const temp = arr[i]; arr[i] = arr[j]; arr[j] = temp;
            i += 1;
        }
        j += 1;
    }
    const temp = arr[i]; arr[i] = arr[high]; arr[high] = temp;
    return i;
}

fn quickSort(arr: []i32, low: usize, high: usize) void {
    if (low >= high or high == 0) return;
    const pi = partition(arr, low, high);
    if (pi > 0) quickSort(arr, low, pi - 1);
    if (pi < high) quickSort(arr, pi + 1, high);
}

pub fn main() !void {
    var arr = [_]i32{ 10, 7, 8, 9, 1, 5 };
    if (arr.len > 0) quickSort(arr, 0, arr.len - 1);
    for (arr) |val| std.debug.print("{} ", .{val});
    std.debug.print("\n", .{});
}

